pub struct Lesson {
    pub n: u32,
    pub title: &'static str,
    pub goal: &'static str,
    pub code: &'static str,
    pub tryit: &'static str,
}

pub const LESSONS: &[Lesson] = &[
    Lesson { n: 1, title: "Hello Cube", goal: "Your first 3D object in one word. OTD already knows a sensible size, color, and place.",
        code: "cube", tryit: "change `cube` to `sphere`, then `torus`, then `pyramid`" },
    Lesson { n: 2, title: "Sizes and Units", goal: "Units glue to the number: 5cm, 30mm, 2m. No unit means centimeters.",
        code: "sphere 5cm\ncube 30mm at (15cm, 0, 0)\nsphere 3cm at (30cm, 0, 0)", tryit: "add `unit: mm` as the first line, then write `sphere 50`" },
    Lesson { n: 3, title: "Colors", goal: "Paint your model. All 147 SVG color names work, plus hex codes.",
        code: "sphere 3cm color: red at (0, 0, 0)\nsphere 3cm color: steelblue at (8cm, 0, 0)\nsphere 3cm color: limegreen at (16cm, 0, 0)", tryit: "try `gold`, `ivory`, or `#1e90ff`" },
    Lesson { n: 4, title: "Materials (real weight)", goal: "Every material carries its true density — mass is computed automatically.",
        code: "sphere 3cm material: gold\ncube 5cm material: oak at (10cm, 0, 0)\nask \"mass?\"", tryit: "swap `gold` for `lead`, `rubber`, `glass` — watch the mass change" },
    Lesson { n: 5, title: "Standing Somewhere", goal: "Y is up. `at (x, y, z)` means where the object stands — its bottom point.",
        code: "cube 4cm\ncube 3cm at (0, 4cm, 0)\nsphere 2cm at (0, 7cm, 0)", tryit: "build stairs: three cubes, each one step higher" },
    Lesson { n: 6, title: "Spin and Grow", goal: "`rotate` spins a shape around its own middle; `scale` grows it.",
        code: "cube 4cm rotate (0, 45deg, 0) color: tomato\nsphere 2cm scale 2 at (12cm, 0, 0) color: turquoise\ntext \"HI\" size: 2cm at (0, 0, 8cm) color: steelblue", tryit: "rotate the letters: chain `rotate (0, 30deg, 0)` onto the text line" },
    Lesson { n: 7, title: "Names are Power", goal: "Variables hold sizes; named objects are shown in the scene.",
        code: "ball_r = 4cm\ngap = 10cm\nball1 = sphere ball_r at (0, 0, 0)\nball2 = sphere ball_r at (gap, 0, 0)\nball3 = sphere ball_r at (gap * 2, 0, 0)", tryit: "change `ball_r` to `2cm` once — all three balls update" },
    Lesson { n: 8, title: "Fuse It (+)", goal: "`+` fuses solids into one; the result keeps the left object's material.",
        code: "snowman = sphere(5cm) + sphere(3.5cm) at (0, 5cm, 0) material: plastic color: white\nhead = sphere(2.5cm) at (0, 7.5cm, 0) color: white\nhat = cone(r: 1.5cm, h: 3cm) at (0, 9.5cm, 0) color: black\nask \"mass?\"", tryit: "fuse the hat on: `add snowman, hat`" },
    Lesson { n: 9, title: "Bite Into It (-)", goal: "Anything right of `-` is removed from the left. This is how holes are made.",
        code: "cheese = cube(10cm, 4cm, 10cm) material: plastic color: gold\ncheese = cheese - sphere(r: 3cm) at (10cm, 2cm, 0)\ncheese = cheese - sphere(r: 2cm) at (5cm, 4cm, 10cm)\nask \"mass?\"", tryit: "cut a hole through: `- cylinder(r: 1.5cm, h: 12cm) at (5cm, 0, 5cm)`" },
    Lesson { n: 10, title: "Hollow Things", goal: "`hollow` removes the inside and leaves walls. Cups, vases, houses.",
        code: "cup = cylinder(top: 40mm, bottom: 30mm, height: 100mm) - hollow(wall: 3mm)\nhandle = torus(radius: 20mm, tube: 6mm) rotate (90deg, 0, 0) at (35mm, 25mm, 0)\nadd cup, handle\nmaterial cup: ceramic\ncolor cup: ivory\nask \"mass?\"", tryit: "thin the wall to `2mm` — the cup gets lighter, exactly as physics says" },
    Lesson { n: 11, title: "Donuts and Rings", goal: "The torus — a ring with thickness, flat like a donut on a table.",
        code: "donut = torus(R: 4cm, tube: 1.5cm) material: plastic color: saddlebrown\npoolRing = torus(R: 6cm, tube: 1cm) at (16cm, 0, 0) color: deepskyblue\nask \"volume?\"", tryit: "rotate a torus `(90deg, 0, 0)` — a hoop facing you (cup handles!)" },
    Lesson { n: 12, title: "Repeat After Me", goal: "`repeat` places n copies stepping by a direction. The magic letter `i` counts from 0.",
        code: "fence = repeat(n: 5, step: (4cm, 0, 0)) cube(1cm, 4cm, 1cm) material: wood\nstairs = repeat(n: 6) cube(4cm, 2cm, 2cm) at (i * 4cm, i * 2cm, 12cm) material: concrete", tryit: "taller fence posts as they go: `cube(1cm, 2cm + i * 1cm, 1cm)`" },
    Lesson { n: 13, title: "Grids and Rings", goal: "`grid` uses i and j; `ring` uses i and the angle a.",
        code: "flower = ring(n: 8, radius: 5cm) sphere 1cm color: pink\ncenter = sphere 1.5cm color: gold", tryit: "make petals face outward: add `rotate (0, a, 0)` after `sphere 1cm`" },
    Lesson { n: 14, title: "Build a Wheel, Use It Four Times", goal: "Reusable parts with parameters: `define` once, `use` anywhere.",
        code: "define wheel(r) = group(torus(r, 1cm, material: rubber), cylinder(r: r + 4mm, h: 2cm, material: steel))\n\nchassis = cube(w: 24cm, d: 12cm, h: 3cm) at (0, 4cm, 0) material: steel color: crimson\nuse wheel(r: 3cm) at (-8cm, 0, -6.2cm)\nuse wheel(r: 3cm) at (8cm, 0, -6.2cm)\nuse wheel(r: 3cm) at (-8cm, 0, 6.2cm)\nuse wheel(r: 3cm) at (8cm, 0, 6.2cm)\nask \"mass?\"", tryit: "change every wheel at once by editing the `define`" },
    Lesson { n: 15, title: "Spin a Profile", goal: "`revolve` spins a 2D outline around the axis — vases, pawns, rooks. Points are (radius, height).",
        code: "vase = revolve [(0, 0), (5cm, 0), (5cm, 1cm), (3cm, 3cm), (4cm, 12cm), (2cm, 14cm)] material: glass\npawn = revolve [(0, 0), (13mm, 0), (13mm, 4mm), (9mm, 8mm), (9mm, 28mm), (14mm, 33mm), (6mm, 36mm)] material: wood at (12cm, 0, 0)\nask \"mass?\"", tryit: "hollow the vase: wrap it as `vase - hollow(wall: 2mm)`" },
    Lesson { n: 16, title: "Flat Shapes, Raised", goal: "`extrude` lifts a flat outline into 3D; `tube` runs a pipe through 3D points.",
        code: "plate = extrude [(0, 0), (12cm, 0), (12cm, 12cm), (0, 12cm)] depth: 5mm material: steel\npipe = tube(r: 8mm, path: [(0, 2cm, 0), (0, 20cm, 0), (10cm, 28cm, 0)]) material: copper at (20cm, 0, 0)", tryit: "extrude a triangle: `[(0,0), (10cm,0), (5cm,8cm)]`" },
    Lesson { n: 17, title: "Springs and Helixes", goal: "`helix` — DNA, springs, drill bits. pitch = height of one turn.",
        code: "spring = helix(radius: 2cm, pitch: 8mm, turns: 6, tube: 2mm) material: steel\ndrill = helix(radius: 1cm, pitch: 2cm, turns: 5, tube: 4mm) material: steel color: silver at (10cm, 0, 0)\nask \"height?\"", tryit: "make a slinky: `radius: 4cm, pitch: 5mm, turns: 10`" },
    Lesson { n: 18, title: "Ask the Model Anything", goal: "The science layer: the model answers questions about itself.",
        code: "ball = sphere 5cm material: gold\nplank = cube(w: 90cm, d: 60cm, h: 4cm) material: oak at (0, 5cm, 0)\nask \"mass?\"\nask \"volume?\"\nask \"density?\"\nask \"center of mass?\"\nask \"will it float?\"\nask \"melting point?\"", tryit: "ask `\"mass of plank?\"` — naming one object narrows the answer" },
    Lesson { n: 19, title: "Drop It, Float It, Topple It", goal: "Real simulations from real material physics.",
        code: "ball = sphere 3cm material: rubber at (0, 40cm, 0)\nball2 = sphere 2cm material: steel at (6cm, 60cm, 0)\nlog = cube 10cm material: oak at (14cm, 30cm, 6cm)\nsimulate: drop\nsimulate: float", tryit: "add `gravity: moon` on line 1, then drop again" },
    Lesson { n: 20, title: "Graduation: the Robot Arm", goal: "Combine everything — parts, booleans, placement, materials — into a machine.",
        code: "scene \"Robot Arm\"\nmaterial: steel\n\nbase = cylinder(r: 9cm, h: 3cm) color: dimgray\ncolumn = cylinder(r: 3.5cm, h: 30cm) at (0, 3cm, 0)\nshoulder = sphere(r: 4.5cm) at (0, 33cm, 0) color: gold\n\nlowerArm = capsule(r: 3cm, h: 28cm) rotate (0, 0, -60deg) at (0, 36cm, 0)\nelbow = sphere(r: 4cm) at (14cm, 48cm, 0) color: gold\nupperArm = capsule(r: 2.5cm, h: 24cm) rotate (0, 0, -25deg) at (12cm, 52cm, 0)\nwrist = sphere(r: 3cm) at (24cm, 62cm, 0) color: gold\n\ngripL = cube(1.5cm, 9cm, 3cm) at (26cm, 62cm, -2.6cm)\ngripR = cube(1.5cm, 9cm, 3cm) at (26cm, 62cm, 2.6cm)\n\nask \"mass?\"\nask \"how many objects?\"", tryit: "you graduated — try the 10 example models, then export to STL" },
    Lesson { n: 21, title: "Melt It Smooth (2.0)", goal: "The 2.0 deep tier: smooth runs the cotan-Laplacian — corners melt, shape survives.",
        code: "scene \"Pebble\"\nrock = sphere(r: 3cm) scale (1.4, 0.8, 1) smooth(n: 5)\nmaterial: concrete\ncolor: dimgray\nask \"mass?\"", tryit: "try n: 0, n: 2, n: 8 — watch the corners melt" },
    Lesson { n: 22, title: "Physics Ropes & Solder (2.0)", goal: "rope hangs in a true catenary (XPBD physics); blend solders solids with a smooth fillet.",
        code: "scene \"Swing Bridge\"\ntowerL = cube(w: 3cm, h: 20cm, d: 3cm) at (0, 0, 0)\ntowerR = cube(w: 3cm, h: 20cm, d: 3cm) at (40cm, 0, 0)\ncable = rope(from: (0, 19cm, 0), to: (40cm, 19cm, 0), thickness: 2mm, sag: 4cm)\nblob = blend(towerL, sphere(r: 4cm) at (2cm, 18cm, 0), gap: 1cm)\nmaterial cable: steel\nask \"cable sag?\"", tryit: "change sag: to 2cm and re-ask — the answer is re-measured, never guessed" },
    Lesson { n: 23, title: "Decide and Repeat (2.1)", goal: "if chooses, for repeats, while keeps going — a whole staircase from four lines.",
        code: "for i = 0 to 7\n  if i is 0\n    cube(20cm, 3cm, 8cm) color: crimson at (10cm, i * 4cm, 0)\n  else\n    cube(20cm, 3cm, 8cm) color: tan at (10cm, i * 4cm, 0)\n  end\nend\ncolumn = cylinder(r: 2cm, h: 36cm) color: dimgray", tryit: "make every third step red: change the if to `if i mod 3 is 0 … else … end`" },
];
